import { GAME_CONFIG } from './config.js';
import { createGameController } from './controller.js';
import { bindInput } from './input.js';
import { render } from './render.js';
import { createInitialState } from './state.js';
import { createTimer } from './timer.js';

const HIT_FEEDBACK_MS = 150;

export function mountApp(doc, options = {}) {
  const byId = (id) => doc.getElementById(id);
  const elements = {
    score: byId('score'),
    time: byId('time'),
    playArea: byId('play-area'),
    target: byId('target'),
    start: byId('start'),
    playAgain: byId('play-again'),
    message: byId('message'),
    win: doc.defaultView,
  };

  const measure =
    options.measure ??
    (() => ({
      areaWidth: elements.playArea.clientWidth,
      areaHeight: elements.playArea.clientHeight,
      targetSize: GAME_CONFIG.targetSizePx,
    }));
  const timer = options.timer ?? createTimer();
  const random = options.random ?? Math.random;

  let previousStatus = createInitialState(GAME_CONFIG).status;
  let feedbackTimeout = null;

  const controller = createGameController({
    config: GAME_CONFIG,
    timer,
    random,
    measure,
    onChange(state) {
      render(elements, state, GAME_CONFIG);
      if (state.status !== previousStatus) {
        if (state.status === 'playing') {
          elements.target.focus();
        } else if (state.status === 'gameOver') {
          elements.playAgain.focus();
        }
        previousStatus = state.status;
      }
    },
  });

  render(elements, controller.getState(), GAME_CONFIG);

  const unbind = bindInput(elements, {
    onStart: () => controller.start(),
    onResize: () => controller.relayout(),
    onHit: () => {
      if (controller.hit()) {
        elements.target.classList.add('hit');
        if (feedbackTimeout !== null) {
          clearTimeout(feedbackTimeout);
        }
        feedbackTimeout = setTimeout(() => {
          feedbackTimeout = null;
          elements.target.classList.remove('hit');
        }, HIT_FEEDBACK_MS);
      }
    },
  });

  function unmount() {
    controller.destroy();
    if (feedbackTimeout !== null) {
      clearTimeout(feedbackTimeout);
      feedbackTimeout = null;
    }
    unbind();
  }

  return { controller, unmount };
}

export const GAME_CONFIG = Object.freeze({
  roundDurationSeconds: 30,
  scorePerHit: 1,
  targetSizePx: 48,
  tickIntervalMs: 1000,
  features: Object.freeze({}),
});

import { computeTargetPosition, clampTargetPosition } from './placement.js';
import { GameStatus, createInitialState } from './state.js';

export function createGameController({ config, timer, random, measure, onChange }) {
  let state = createInitialState(config);

  function notify() {
    if (onChange) {
      onChange(getState());
    }
  }

  function getState() {
    return { ...state, target: state.target ? { ...state.target } : null };
  }

  function tick() {
    if (state.status !== GameStatus.PLAYING) {
      return;
    }
    state.remainingSeconds = Math.max(0, state.remainingSeconds - 1);
    if (state.remainingSeconds === 0) {
      timer.stop();
      state.status = GameStatus.GAME_OVER;
      state.target = null;
    }
    notify();
  }

  function start() {
    if (state.status === GameStatus.PLAYING) {
      return;
    }
    timer.stop();
    const target = computeTargetPosition(measure(), random);
    state.score = 0;
    state.remainingSeconds = config.roundDurationSeconds;
    state.status = GameStatus.PLAYING;
    state.target = target;
    timer.start(tick, config.tickIntervalMs);
    notify();
  }

  function hit() {
    if (state.status !== GameStatus.PLAYING) {
      return false;
    }
    const target = computeTargetPosition(measure(), random);
    state.score += config.scorePerHit;
    state.target = target;
    notify();
    return true;
  }

  function relayout() {
    if (state.status !== GameStatus.PLAYING) {
      return;
    }
    state.target = clampTargetPosition(state.target, measure());
    notify();
  }

  function destroy() {
    timer.stop();
  }

  return { getState, start, hit, relayout, destroy };
}

export function bindInput(elements, handlers) {
  const { start, target, playAgain, win } = elements;
  const { onStart, onHit, onResize } = handlers;

  start.addEventListener('click', onStart);
  target.addEventListener('click', onHit);
  playAgain.addEventListener('click', onStart);
  win.addEventListener('resize', onResize);

  return function unbind() {
    start.removeEventListener('click', onStart);
    target.removeEventListener('click', onHit);
    playAgain.removeEventListener('click', onStart);
    win.removeEventListener('resize', onResize);
  };
}

function computeBounds({ areaWidth, areaHeight, targetSize }) {
  return {
    maxX: Math.max(0, Math.floor(areaWidth - targetSize)),
    maxY: Math.max(0, Math.floor(areaHeight - targetSize)),
  };
}

export function computeTargetPosition(area, random) {
  const { maxX, maxY } = computeBounds(area);
  return {
    x: Math.floor(random() * (maxX + 1)),
    y: Math.floor(random() * (maxY + 1)),
  };
}

export function clampTargetPosition(target, area) {
  const { maxX, maxY } = computeBounds(area);
  return {
    x: Math.min(maxX, Math.max(0, target.x)),
    y: Math.min(maxY, Math.max(0, target.y)),
  };
}

import { GameStatus } from './state.js';

export function render(elements, state, config) {
  const { score, time, target, start, playAgain, message } = elements;
  score.textContent = String(state.score);
  time.textContent = String(state.remainingSeconds);

  target.hidden = state.status !== GameStatus.PLAYING;
  start.hidden = state.status !== GameStatus.READY;
  playAgain.hidden = state.status !== GameStatus.GAME_OVER;

  if (state.status === GameStatus.PLAYING && state.target) {
    target.style.left = `${state.target.x}px`;
    target.style.top = `${state.target.y}px`;
    target.style.width = `${config.targetSizePx}px`;
    target.style.height = `${config.targetSizePx}px`;
  }

  if (state.status === GameStatus.READY) {
    message.textContent = `Press Start to begin a ${config.roundDurationSeconds}-second round.`;
  } else if (state.status === GameStatus.GAME_OVER) {
    message.textContent = `Game over! Final score: ${state.score}.`;
  } else {
    message.textContent = '';
  }
}

export const GameStatus = Object.freeze({
  READY: 'ready',
  PLAYING: 'playing',
  GAME_OVER: 'gameOver',
});

export function createInitialState(config) {
  return {
    status: GameStatus.READY,
    score: 0,
    remainingSeconds: config.roundDurationSeconds,
    target: null,
  };
}

[hidden] {
  display: none !important;
}

body {
  margin: 0;
  padding: 16px;
  font-family: system-ui, sans-serif;
  color: #1a1a1a;
  background: #ffffff;
}

header {
  margin-bottom: 16px;
}

h1 {
  margin: 0 0 8px;
}

.status-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 16px;
  align-items: baseline;
  margin-bottom: 12px;
  font-size: 1.25rem;
}

#play-area {
  position: relative;
  width: 100%;
  max-width: 640px;
  min-height: 300px;
  overflow: hidden;
  border: 2px solid #1a1a1a;
  box-sizing: border-box;
  background: #f2f2f2;
}

#target {
  position: absolute;
  padding: 0;
  border: 4px double #1a1a1a;
  border-radius: 50%;
  background: #ffd23f;
  cursor: pointer;
  transition: transform 100ms ease-out;
}

#target.hit {
  transform: scale(1.2);
}

.actions {
  margin: 12px 0;
}

button {
  font: inherit;
  padding: 8px 16px;
}

button:focus-visible {
  outline: 3px solid #0050d0;
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  #target {
    animation: none;
    transition: none;
  }
}

export function createTimer({ setIntervalFn, clearIntervalFn } = {}) {
  let handle = null;
  let active = false;

  function stop() {
    if (!active) {
      return;
    }
    const clear = clearIntervalFn ?? globalThis.clearInterval;
    clear(handle);
    handle = null;
    active = false;
  }

  function start(onTick, intervalMs) {
    stop();
    const schedule = setIntervalFn ?? globalThis.setInterval;
    handle = schedule(onTick, intervalMs);
    active = true;
  }

  function isRunning() {
    return active;
  }

  return { start, stop, isRunning };
}
